          "id": "code-ml-07-1-ch07_1_diag",
          "title": "Diagnostik Hoerl-Kennard: Kurva Bias^2-Variance & Analytical LOOCV",
          "language": "python",
          "filename": "07_1_hoerl_kennard_loocv_audit.py",
          "code": "import numpy as np\n\nrng = np.random.default_rng(42)\nn, p = 100, 10\n\n# Desain tetap dengan multikolinearitas tinggi (untuk mengukur Bias^2 & Variance eksak)\nU_q, _ = np.linalg.qr(rng.normal(size=(n, p)))\nV_q, _ = np.linalg.qr(rng.normal(size=(p, p)))\nsing_vals = np.array([15.0, 11.0, 8.0, 4.0, 1.5, 0.6, 0.25, 0.12, 0.06, 0.03])\nX = U_q @ np.diag(sing_vals) @ V_q.T\nbeta_true = np.array([1.5, -1.2, 0.9, 0.7, -0.5, 0.4, -0.3, 0.2, 0.1, -0.1])\nsigma_eps = 1.2\n\n# 1. Monte Carlo 80 replikasi untuk memverifikasi Teorema Hoerl-Kennard (1970)\nlambdas = [0.0, 0.005, 0.02, 0.1, 0.5, 2.0, 10.0, 50.0]\nn_rep = 80\neps_all = rng.normal(0.0, sigma_eps, size=(n_rep, n))\n\nprint(\"=== Audit Bias^2 + Variance (Hoerl-Kennard) & Analytical LOOCV ===\")\nprint(\"lambda  | df(lam) |  Bias^2  | Variance | Total MSE | Analyt LOOCV\")\nprint(\"-\" * 67)\ny_one = X @ beta_true + eps_all[0]\nfor lam in lambdas:\n    # Solver SVD sekali per lambda\n    inv_term = sing_vals / (sing_vals ** 2 + lam)\n    M = V_q @ np.diag(inv_term) @ U_q.T  # shape (p, n)\n    betas = eps_all @ M.T + (M @ (X @ beta_true))[None, :]\n    mean_b = betas.mean(axis=0)\n    bias2 = float(np.sum((mean_b - beta_true) ** 2))\n    var_b = float(np.mean(np.sum((betas - mean_b) ** 2, axis=1)))\n    total_mse = bias2 + var_b\n    df_eff = float(np.sum((sing_vals ** 2) / (sing_vals ** 2 + lam)))\n\n    # Analytical Hat-Matrix LOOCV pada sampel pertama: mean(((y - y_hat)/(1 - h_ii))^2)\n    h_diag = np.sum((U_q ** 2) * ((sing_vals ** 2) / (sing_vals ** 2 + lam))[None, :], axis=1)\n    y_hat = X @ (M @ y_one)\n    loocv = float(np.mean(((y_one - y_hat) / np.maximum(1.0 - h_diag, 1e-8)) ** 2))\n    print(f\"{lam:7.3f} | {df_eff:7.3f} | {bias2:8.4f} | {var_b:8.4f} | {total_mse:9.4f} | {loocv:12.4f}\")",
          "expectedOutput": "=== Audit Bias^2 + Variance (Hoerl-Kennard) & Analytical LOOCV ===\nlambda  | df(lam) |  Bias^2  | Variance | Total MSE | Analyt LOOCV\n-------------------------------------------------------------------\n  0.000 |  10.000 |   6.2954 | 2818.6110 | 2824.9065 |       1.7116\n  0.005 |   8.223 |   3.7616 | 199.2154 |  202.9770 |       1.7000\n  0.020 |   7.309 |   1.9504 |  45.0350 |   46.9854 |       1.6847\n  0.100 |   6.285 |   1.0286 |   7.8968 |    8.9254 |       1.6539\n  0.500 |   5.340 |   1.0002 |   1.6350 |    2.6352 |       1.6240\n  2.000 |   4.555 |   1.2044 |   0.4395 |    1.6439 |       1.6111\n 10.000 |   3.588 |   1.7390 |   0.1023 |    1.8413 |       1.6322\n 50.000 |   2.381 |   2.6831 |   0.0252 |    2.7082 |       1.8323",
          "actualOutput": "=== Audit Bias^2 + Variance (Hoerl-Kennard) & Analytical LOOCV ===\nlambda  | df(lam) |  Bias^2  | Variance | Total MSE | Analyt LOOCV\n-------------------------------------------------------------------\n  0.000 |  10.000 |   6.2954 | 2818.6110 | 2824.9065 |       1.7116\n  0.005 |   8.223 |   3.7616 | 199.2154 |  202.9770 |       1.7000\n  0.020 |   7.309 |   1.9504 |  45.0350 |   46.9854 |       1.6847\n  0.100 |   6.285 |   1.0286 |   7.8968 |    8.9254 |       1.6539\n  0.500 |   5.340 |   1.0002 |   1.6350 |    2.6352 |       1.6240\n  2.000 |   4.555 |   1.2044 |   0.4395 |    1.6439 |       1.6111\n 10.000 |   3.588 |   1.7390 |   0.1023 |    1.8413 |       1.6322\n 50.000 |   2.381 |   2.6831 |   0.0252 |    2.7082 |       1.8323",
