          "code": "import numpy as np\n\ndef soft_thresh(z: float, tau: float) -> float:\n    return np.sign(z) * max(abs(z) - tau, 0.0)\n\ndef elasticnet_cd(Xc: np.ndarray, yc: np.ndarray, alpha: float, l1_ratio: float,\n                  beta_init=None, max_iter: int = 1000, tol: float = 1e-7):\n    \"\"\"Coordinate Descent ElasticNet mendukung cold-start & warm-start.\"\"\"\n    n, p = Xc.shape\n    l1_pen = alpha * l1_ratio\n    l2_pen = alpha * (1.0 - l1_ratio)\n    col_sq = np.sum(Xc ** 2, axis=0) / n\n\n    beta = np.zeros(p) if beta_init is None else beta_init.copy()\n    r = yc - Xc @ beta\n    iters = 0\n    for it in range(1, max_iter + 1):\n        max_diff = 0.0\n        for j in range(p):\n            old_b = beta[j]\n            rho_j = float(np.dot(Xc[:, j], r) / n + col_sq[j] * old_b)\n            new_b = soft_thresh(rho_j, l1_pen) / (col_sq[j] + l2_pen)\n            if new_b != old_b:\n                r -= Xc[:, j] * (new_b - old_b)\n                beta[j] = new_b\n                max_diff = max(max_diff, abs(new_b - old_b))\n        iters = it\n        if max_diff < tol:\n            break\n    return beta, iters\n\nrng = np.random.default_rng(42)\nn, p = 180, 24\n# Grup 0..3 saling berkorelasi tinggi (rho ~ 0.98)\nz1 = rng.normal(0.0, 1.0, size=n)\ngrp1 = np.column_stack([z1 + rng.normal(0.0, 0.14, size=n) for _ in range(4)])\nnoise_X = rng.normal(0.0, 1.0, size=(n, p - 4))\nX = np.column_stack([grp1, noise_X])\nXc = (X - X.mean(axis=0)) / X.std(axis=0)\ny = 3.0 * z1 + rng.normal(0.0, 1.0, size=n)\nyc = y - y.mean()\n\n# 1. Benchmark Cold-Start vs Warm-Start sepanjang 35 titik Regularization Path\nl1_ratio = 0.5\nalpha_max = float(np.max(np.abs((Xc.T @ yc) / n)) / l1_ratio)\nalphas = np.geomspace(alpha_max, alpha_max * 0.02, 35)\n\ncold_iters, warm_iters = 0, 0\nbeta_warm = np.zeros(p)\nbeta_mid = None\nfor idx, a in enumerate(alphas):\n    _, ic = elasticnet_cd(Xc, yc, float(a), l1_ratio, beta_init=None)\n    beta_warm, iw = elasticnet_cd(Xc, yc, float(a), l1_ratio, beta_init=beta_warm)\n    cold_iters += ic\n    warm_iters += iw\n    if idx == 20:\n        beta_mid = (float(a), beta_warm.copy())\n\n# 2. Verifikasi Teorema Grouping Effect Zou & Hastie (2005)\na_chk, b_chk = beta_mid\nlam2 = a_chk * (1.0 - l1_ratio)\nrho_01 = float(np.dot(Xc[:, 0], Xc[:, 1]) / n)\nlhs_diff = abs(float(b_chk[0] - b_chk[1]))\nrhs_bound = float((np.linalg.norm(yc) / (np.sqrt(n) * lam2)) * np.sqrt(2.0 * (1.0 - rho_01)))\n\nprint(\"=== Benchmark Regularization Path (35 titik alpha, l1_ratio=0.5) ===\")\nprint(f\"Total iterasi Cold-Start : {cold_iters}\")\nprint(f\"Total iterasi Warm-Start : {warm_iters} (percepatan {cold_iters / warm_iters:.2f}x)\")\nprint(f\"=== Verifikasi Teorema Grouping Effect Zou-Hastie (alpha={a_chk:.4f}) ===\")\nprint(f\"Koefisien Grup Berkorelasi (fitur 0..3): {np.round(b_chk[:4], 4)}\")\nprint(f\"Korelasi sampel rho_01 = {rho_01:.4f}\")\nprint(f\"|beta_0 - beta_1|      = {lhs_diff:.4f} <= Batas Teoretis {rhs_bound:.4f} (LULUS={lhs_diff <= rhs_bound + 1e-9})\")",
