          "code": "import numpy as np\nfrom sklearn.linear_model import ElasticNet, ElasticNetCV\nfrom sklearn.metrics import root_mean_squared_error\nfrom sklearn.model_selection import train_test_split\nfrom sklearn.preprocessing import StandardScaler\n\nrng = np.random.default_rng(42)\nn, p = 260, 70\nz1, z2 = rng.normal(size=n), rng.normal(size=n)\nX = np.column_stack([\n    z1 + rng.normal(0, 0.2, n), z1 + rng.normal(0, 0.2, n), z1 + rng.normal(0, 0.2, n),\n    z2 + rng.normal(0, 0.2, n), z2 + rng.normal(0, 0.2, n), z2 + rng.normal(0, 0.2, n),\n    rng.normal(0, 1.0, size=(n, p - 6)),\n])\ny = 2.8 * z1 - 2.4 * z2 + rng.normal(0.0, 1.8, size=n)\n\nX_tr_raw, X_te_raw, y_tr, y_te = train_test_split(X, y, test_size=0.30, random_state=42)\nscaler = StandardScaler().fit(X_tr_raw)\nX_tr, X_te = scaler.transform(X_tr_raw), scaler.transform(X_te_raw)\n\nrho = 0.5\ncv_model = ElasticNetCV(l1_ratio=rho, alphas=60, cv=5, random_state=42, max_iter=5000).fit(X_tr, y_tr)\nalphas = cv_model.alphas_          # urutan menurun (besar -> kecil)\nmse_folds = cv_model.mse_path_     # shape: (n_alphas, n_folds)\nmean_mse = mse_folds.mean(axis=1)\nse_mse = mse_folds.std(axis=1, ddof=1) / np.sqrt(mse_folds.shape[1])\n\nidx_min = int(np.argmin(mean_mse))\nalpha_min = float(alphas[idx_min])\nthreshold_1se = float(mean_mse[idx_min] + se_mse[idx_min])\n\n# Aturan 1-SE: pilih alpha TERBESAR yang mean_mse <= threshold_1se\neligible = np.where(mean_mse <= threshold_1se)[0]\nidx_1se = int(eligible[np.argmax(alphas[eligible])])\nalpha_1se = float(alphas[idx_1se])\n\nm_min = ElasticNet(alpha=alpha_min, l1_ratio=rho, max_iter=5000).fit(X_tr, y_tr)\nm_1se = ElasticNet(alpha=alpha_1se, l1_ratio=rho, max_iter=5000).fit(X_tr, y_tr)\n\nrmse_min = root_mean_squared_error(y_te, m_min.predict(X_te))\nrmse_1se = root_mean_squared_error(y_te, m_1se.predict(X_te))\n\nnnz_min = int(np.sum(np.abs(m_min.coef_) > 1e-6))\nnnz_1se = int(np.sum(np.abs(m_1se.coef_) > 1e-6))\nfp_min = int(np.sum(np.abs(m_min.coef_[6:]) > 1e-6))\nfp_1se = int(np.sum(np.abs(m_1se.coef_[6:]) > 1e-6))\n\nprint(\"=== Audit Aturan 1-SE (Parsimony vs Akurasi) pada ElasticNetCV ===\")\nprint(f\"CV MSE minimum = {mean_mse[idx_min]:.4f} +- SE {se_mse[idx_min]:.4f} -> Ambang 1-SE = {threshold_1se:.4f}\")\nprint(f\"Model alpha_min ({alpha_min:.4f}): Fitur Aktif={nnz_min:2d} (FalsePos={fp_min:2d}) | Test RMSE={rmse_min:.4f}\")\nprint(f\"Model alpha_1SE ({alpha_1se:.4f}): Fitur Aktif={nnz_1se:2d} (FalsePos={fp_1se:2d}) | Test RMSE={rmse_1se:.4f}\")\nprint(f\"Pengurangan Fitur Noise  : {fp_min - fp_1se} fitur derau berhasil dipangkas tanpa merusak akurasi!\")",
