          "id": "code-ml-07-4-ch07_4_sklearn",
          "title": "Group Lasso Block CD (One-Hot) & Relaxed Group Lasso Pipeline",
          "language": "python",
          "filename": "07_4_group_lasso_onehot_relaxed.py",
          "code": "import numpy as np\nfrom sklearn.linear_model import LassoCV, RidgeCV\nfrom sklearn.metrics import root_mean_squared_error\nfrom sklearn.model_selection import train_test_split\nfrom sklearn.preprocessing import OneHotEncoder, StandardScaler\n\ndef group_lasso_bcd(X: np.ndarray, y: np.ndarray, groups: list[np.ndarray], lam: float, max_iter: int = 500):\n    \"\"\"Proximal Block Coordinate Descent Group Lasso dengan bobot sqrt(p_g).\"\"\"\n    n, p = X.shape\n    yc = y - y.mean()\n    beta = np.zeros(p)\n    r = yc.copy()\n    # Pra-hitung konstanta Lipschitz per blok: L_g = sigma_max(X_g)^2 / n\n    L_blocks = [float(np.linalg.norm(X[:, g], ord=2) ** 2 / n) + 1e-12 for g in groups]\n    for _ in range(max_iter):\n        max_diff = 0.0\n        for g_idx, L_g in zip(groups, L_blocks):\n            Xg = X[:, g_idx]\n            old_bg = beta[g_idx].copy()\n            # Gradien eksak pada titik beta saat ini memakai residual penuh r = yc - X @ beta\n            grad_g = -(Xg.T @ r) / n\n            z_g = old_bg - grad_g / L_g\n            z_norm = float(np.linalg.norm(z_g))\n            thresh = (lam * np.sqrt(len(g_idx))) / L_g\n            if z_norm <= thresh:\n                new_bg = np.zeros_like(old_bg)\n            else:\n                new_bg = z_g * (1.0 - thresh / z_norm)\n            delta = new_bg - old_bg\n            if np.any(delta != 0.0):\n                r -= Xg @ delta\n                beta[g_idx] = new_bg\n                max_diff = max(max_diff, float(np.linalg.norm(delta)))\n        if max_diff < 1e-7:\n            break\n    return float(y.mean()), beta\n\nrng = np.random.default_rng(42)\nn = 360\n# 4 variabel kategorik (masing-masing 5 level -> 4 blok one-hot). Hanya Grup 0 & 1 aktif!\ncats = rng.integers(0, 5, size=(n, 4))\nohe = OneHotEncoder(sparse_output=False)\nX_ohe = ohe.fit_transform(cats)\nX_ohe_c = X_ohe - X_ohe.mean(axis=0)\n\nw_grp_true = np.zeros(20)\nw_grp_true[0:5] = [2.4, -1.8, 0.9, -0.5, -1.0]    # Grup 0 aktif penuh\nw_grp_true[5:10] = [-2.0, 1.5, 1.2, -0.4, -0.3]   # Grup 1 aktif penuh\n# Grup 2 (10:15) dan Grup 3 (15:20) murni noise (0)\ny = 20.0 + X_ohe_c @ w_grp_true + rng.normal(0.0, 0.9, size=n)\n\nX_tr, X_te, y_tr, y_te = train_test_split(X_ohe_c, y, test_size=0.30, random_state=42)\ngroups = [np.arange(0, 5), np.arange(5, 10), np.arange(10, 15), np.arange(15, 20)]\n\n# 1. Lasso standar (memecah blok one-hot secara parsial)\nlas = LassoCV(cv=5, random_state=42).fit(X_tr, y_tr)\n# 2. Group Lasso (seleksi blok serentak -> matikan Grup 2 & 3 ke 0/5!)\nb0_gl, b_gl = group_lasso_bcd(X_tr, y_tr, groups, lam=0.08)\n# 3. Relaxed Group Lasso (debiasing RidgeCV ringan hanya pada blok aktif terpilih!)\nactive_cols = np.where(np.abs(b_gl) > 1e-6)[0]\nrefit_ridge = RidgeCV(alphas=np.logspace(-3, 2, 20)).fit(X_tr[:, active_cols], y_tr)\n\nprint(\"=== Seleksi Blok Fitur One-Hot (4 Grup x 5 Level; Sejati Aktif: Grup 0 & 1) ===\")\nfor g_id, g_idx in enumerate(groups):\n    n_las = int(np.sum(np.abs(las.coef_[g_idx]) > 1e-5))\n    n_gl = int(np.sum(np.abs(b_gl[g_idx]) > 1e-5))\n    print(f\"  Grup {g_id} (sejati={'AKTIF' if g_id < 2 else 'NOL  '}): Lasso aktif={n_las}/5 | GroupLasso aktif={n_gl}/5\")\n\nrmse_las = root_mean_squared_error(y_te, las.predict(X_te))\nrmse_gl = root_mean_squared_error(y_te, b0_gl + X_te @ b_gl)\nrmse_rel = root_mean_squared_error(y_te, refit_ridge.predict(X_te[:, active_cols]))\nprint(f\"Test RMSE -> Lasso={rmse_las:.4f} | GroupLasso={rmse_gl:.4f} | Relaxed GroupLasso={rmse_rel:.4f}\")",
          "expectedOutput": "=== Seleksi Blok Fitur One-Hot (4 Grup x 5 Level; Sejati Aktif: Grup 0 & 1) ===\n  Grup 0 (sejati=AKTIF): Lasso aktif=4/5 | GroupLasso aktif=5/5\n  Grup 1 (sejati=AKTIF): Lasso aktif=4/5 | GroupLasso aktif=5/5\n  Grup 2 (sejati=NOL  ): Lasso aktif=3/5 | GroupLasso aktif=0/5\n  Grup 3 (sejati=NOL  ): Lasso aktif=4/5 | GroupLasso aktif=0/5\nTest RMSE -> Lasso=0.9500 | GroupLasso=1.1604 | Relaxed GroupLasso=0.9530",
          "actualOutput": "=== Seleksi Blok Fitur One-Hot (4 Grup x 5 Level; Sejati Aktif: Grup 0 & 1) ===\n  Grup 0 (sejati=AKTIF): Lasso aktif=4/5 | GroupLasso aktif=5/5\n  Grup 1 (sejati=AKTIF): Lasso aktif=4/5 | GroupLasso aktif=5/5\n  Grup 2 (sejati=NOL  ): Lasso aktif=3/5 | GroupLasso aktif=0/5\n  Grup 3 (sejati=NOL  ): Lasso aktif=4/5 | GroupLasso aktif=0/5\nTest RMSE -> Lasso=0.9500 | GroupLasso=1.1604 | Relaxed GroupLasso=0.9530",
