          "title": "Audit Shrinkage Bias Lintas Magnitudo Sinyal (0.8 vs 2.5 vs 8.0)",
          "language": "python",
          "filename": "07_4_shrinkage_bias_magnitude_audit.py",
          "code": "import numpy as np\nfrom sklearn.linear_model import LassoCV, RidgeCV\n\ndef soft_thresh(z: float, tau: float) -> float:\n    return float(np.sign(z) * max(abs(z) - tau, 0.0))\n\ndef wlasso_cd(Xc, yc, weights, beta_init=None, max_iter=400):\n    n, p = Xc.shape\n    col_sq = np.sum(Xc ** 2, axis=0) / n\n    beta = np.zeros(p) if beta_init is None else beta_init.copy()\n    r = yc - Xc @ beta\n    for _ in range(max_iter):\n        diff = 0.0\n        for j in range(p):\n            old_b = beta[j]\n            rho = float(np.dot(Xc[:, j], r) / n + col_sq[j] * old_b)\n            new_b = soft_thresh(rho, float(weights[j])) / col_sq[j]\n            if new_b != old_b:\n                r -= Xc[:, j] * (new_b - old_b)\n                beta[j] = new_b\n                diff = max(diff, abs(new_b - old_b))\n        if diff < 1e-7:\n            break\n    return beta\n\nrng = np.random.default_rng(42)\nn, p = 260, 50\n# Audit bias penyusutan pada 3 tingkat besaran sinyal sejati: kecil (0.8), sedang (2.5), besar (8.0)\nbeta_true = np.zeros(p)\nbeta_true[:3] = [0.8, 2.5, 8.0]\n\nbias_records = {k: [] for k in [\"LassoCV\", \"RelaxedLasso\", \"SCAD_LLA\"]}\nfp_records = {k: [] for k in [\"LassoCV\", \"RelaxedLasso\", \"SCAD_LLA\"]}\n\nfor rep in range(20):\n    X = rng.normal(0.0, 1.0, size=(n, p))\n    X = (X - X.mean(axis=0)) / X.std(axis=0)\n    y = X @ beta_true + rng.normal(0.0, 1.5, size=n)\n    yc = y - y.mean()\n\n    # 1. LassoCV (memakai alpha_1se ringan: 1.5x alpha_min agar seleksi bersih)\n    lcv = LassoCV(cv=5, random_state=42).fit(X, yc)\n    lam_sel = float(lcv.alpha_) * 1.6\n    b_las = wlasso_cd(X, yc, np.full(p, lam_sel))\n\n    # 2. Relaxed Lasso (refit Ridge kecil pada support Lasso)\n    supp = np.where(np.abs(b_las) > 1e-6)[0]\n    b_rel = np.zeros(p)\n    if len(supp) > 0:\n        b_rel[supp] = RidgeCV(alphas=[1e-4, 1e-2, 0.1, 1.0]).fit(X[:, supp], yc).coef_\n\n    # 3. SCAD-LLA 5 iterasi\n    b_scad = b_las.copy()\n    for _ in range(5):\n        w = np.where(np.abs(b_scad) <= lam_sel, lam_sel, np.maximum(3.7 * lam_sel - np.abs(b_scad), 0.0) / 2.7)\n        b_scad = wlasso_cd(X, yc, w, beta_init=b_scad)\n\n    for name, b_hat in [(\"LassoCV\", b_las), (\"RelaxedLasso\", b_rel), (\"SCAD_LLA\", b_scad)]:\n        bias_records[name].append(b_hat[:3] - beta_true[:3])\n        fp_records[name].append(int(np.sum(np.abs(b_hat[3:]) > 1e-6)))\n\nprint(\"=== Audit Shrinkage Bias Lintas Magnitudo Sinyal (20 Replikasi, p=50) ===\")\nprint(\"Metode       | Bias b*=0.8 | Bias b*=2.5 | Bias b*=8.0 | Mean FalsePos\")\nprint(\"-\" * 72)\nfor name in [\"LassoCV\", \"RelaxedLasso\", \"SCAD_LLA\"]:\n    mb = np.mean(bias_records[name], axis=0)\n    mfp = float(np.mean(fp_records[name]))\n    print(f\"{name:12s} | {mb[0]:+11.4f} | {mb[1]:+11.4f} | {mb[2]:+11.4f} | {mfp:13.2f}\")",
          "expectedOutput": "=== Audit Shrinkage Bias Lintas Magnitudo Sinyal (20 Replikasi, p=50) ===\nMetode       | Bias b*=0.8 | Bias b*=2.5 | Bias b*=8.0 | Mean FalsePos\n------------------------------------------------------------------------\nLassoCV      |     -0.1950 |     -0.2311 |     -0.2448 |          1.70\nRelaxedLasso |     +0.0171 |     -0.0162 |     -0.0339 |          1.70\nSCAD_LLA     |     -0.0185 |     -0.0138 |     -0.0254 |          1.60",
          "actualOutput": "=== Audit Shrinkage Bias Lintas Magnitudo Sinyal (20 Replikasi, p=50) ===\nMetode       | Bias b*=0.8 | Bias b*=2.5 | Bias b*=8.0 | Mean FalsePos\n------------------------------------------------------------------------\nLassoCV      |     -0.1950 |     -0.2311 |     -0.2448 |          1.70\nRelaxedLasso |     +0.0171 |     -0.0162 |     -0.0339 |          1.70\nSCAD_LLA     |     -0.0185 |     -0.0138 |     -0.0254 |          1.60",
